#!/usr/bin/env node
// scripts/sync-github-action-bin.mjs
//
// PURPOSE (closes MANIFEST "החסר הבא" #2/#3, v255-256 debt: "bin/tfa.mjs ב-github-action
// הוא עותק סטטי של sdk/cli/bin/tfa.mjs; דרוש CI sync script או bundler שמונע drift"):
//
// `sdk/cli/bin/tfa.mjs` is the SINGLE SOURCE OF TRUTH for the TFA CLI binary.
// `sdk/github-action/bin/tfa.mjs` is a DERIVED COPY, regenerated by this script.
// Without this script, the two files could silently diverge (someone fixes a bug
// in one without touching the other) and the only existing safety net
// (tests/sdk-cli/tfa-github-action-governance.test.ts) only checked that the
// VERSION *string* matched — not that the actual command logic did.
//
// USAGE
//   node scripts/sync-github-action-bin.mjs           # regenerate the copy
//   node scripts/sync-github-action-bin.mjs --check   # CI mode: exit 1 if the
//                                                       # checked-in copy is stale
//                                                       # (no write — for CI gates)
//
// HOW IT WORKS
//   1. Read sdk/cli/bin/tfa.mjs (the canonical source) verbatim.
//   2. Prepend a short "GENERATED FILE — DO NOT EDIT DIRECTLY" banner (as a
//      comment, so the shebang on line 1 of the canonical file is preserved
//      as line 1 of the OUTPUT too — Node requires the shebang to be the very
//      first line of the file to be honoured as an interpreter directive).
//   3. Write (or, in --check mode, compare) sdk/github-action/bin/tfa.mjs.
//
// fail-closed: any I/O error (missing source, unreadable, etc.) exits non-zero
// with a clear message — never silently no-ops.

import { readFileSync, writeFileSync, existsSync, chmodSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const __dirname = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = join(__dirname, "..");

const SOURCE_PATH = join(REPO_ROOT, "sdk/cli/bin/tfa.mjs");
const TARGET_PATH = join(REPO_ROOT, "sdk/github-action/bin/tfa.mjs");

const GENERATED_BANNER = [
  "// ── GENERATED FILE — DO NOT EDIT DIRECTLY ──────────────────────────────────",
  "// This file is a byte-for-byte derived copy of sdk/cli/bin/tfa.mjs, the",
  "// canonical TFA CLI binary. It is regenerated by:",
  "//   node scripts/sync-github-action-bin.mjs",
  "// Edit sdk/cli/bin/tfa.mjs instead, then re-run the sync script. CI checks",
  "// this file is up to date via `node scripts/sync-github-action-bin.mjs --check`",
  "// (see tests/sdk-cli/tfa-github-action-governance.test.ts).",
  "// ─────────────────────────────────────────────────────────────────────────",
  "",
].join("\n");

/**
 * Build the derived github-action bin content from the canonical CLI source.
 * The shebang (line 1 of the source) is kept as line 1 of the output — Node
 * only honours `#!/usr/bin/env node` as an interpreter directive on the very
 * first line, so the banner is inserted AFTER it, not before.
 *
 * fail-closed: throws if `source` doesn't start with a shebang line, rather
 * than silently producing a binary Node would refuse to execute directly.
 */
export function buildDerivedContent(source) {
  const newlineIdx = source.indexOf("\n");
  if (newlineIdx === -1 || !source.startsWith("#!")) {
    throw new Error("sync-github-action-bin: source file does not start with a shebang line — refusing to generate a non-executable copy");
  }
  const shebangLine = source.slice(0, newlineIdx + 1);
  const rest = source.slice(newlineIdx + 1);
  return shebangLine + GENERATED_BANNER + rest;
}

function main() {
  const checkOnly = process.argv.includes("--check");

  if (!existsSync(SOURCE_PATH)) {
    console.error(`[sync-github-action-bin] FAIL: canonical source not found: ${SOURCE_PATH}`);
    process.exit(1);
  }

  const source = readFileSync(SOURCE_PATH, "utf8");
  const derived = buildDerivedContent(source);

  if (checkOnly) {
    if (!existsSync(TARGET_PATH)) {
      console.error(`[sync-github-action-bin] DRIFT: ${TARGET_PATH} does not exist. Run without --check to generate it.`);
      process.exit(1);
    }
    const existing = readFileSync(TARGET_PATH, "utf8");
    if (existing !== derived) {
      console.error(
        "[sync-github-action-bin] DRIFT DETECTED: sdk/github-action/bin/tfa.mjs is out of sync " +
        "with sdk/cli/bin/tfa.mjs. Run `node scripts/sync-github-action-bin.mjs` to regenerate, " +
        "then commit the result.",
      );
      process.exit(1);
    }
    console.log("[sync-github-action-bin] OK: sdk/github-action/bin/tfa.mjs is in sync with sdk/cli/bin/tfa.mjs.");
    process.exit(0);
  }

  writeFileSync(TARGET_PATH, derived, "utf8");
  try {
    chmodSync(TARGET_PATH, 0o755); // keep the binary executable, matching the source
  } catch {
    // chmod can fail on some filesystems (e.g. certain CI sandboxes) — non-fatal,
    // the file content is still correct; execution will just need `node <path>`.
  }
  console.log(`[sync-github-action-bin] Regenerated ${TARGET_PATH} from ${SOURCE_PATH}.`);
}

// Only run main() when executed directly (not when imported by tests).
if (import.meta.url === `file://${process.argv[1]}`) {
  main();
}
